            delay <= {delay[2:0], data};
        else if (state == 7)
            delay <= {delay[2:0], data};
        else if (state == 8 && cycle_cnt == 999 && delay != 0)
            delay <= delay - 1;
        else
            delay <= delay;
    end
end
always @(posedge clk) begin
    begin
        if (reset)
            counting <= 0;
        else if (next_state == 8)
            counting <= 1;
        else
            counting <= 0;
    end
end
always @(posedge clk) begin
    begin
        if (reset)
            done <= 0;
        else if (next_state == 9)
